SANDBOX = P("sandboxes", "Sandboxes", """<div class="ph" id="h"></div><div class="bodyx" id="b"></div>""", r"""
const kb=x=>x>1048576?(x/1048576).toFixed(1)+' MB':((x||0)/1024).toFixed(0)+' KB';
async function list(){const [sb,sn,rt,vc]=await Promise.all([api('api/sandboxes'),api('api/sandbox_snapshots').catch(()=>[]),api('api/sandbox_runtime').catch(()=>({})),api('api/v2/sandboxes/boxes?limit=200').then(x=>x.items||[]).catch(()=>[])]);
 $('h').innerHTML=hdr('terminal','Sandboxes','',`<button id="ns">${ICN('plus')}Sandbox</button>`);
 $('ns').onclick=async()=>{const n=prompt('Sandbox name','sandbox');if(!n)return;try{const r=await api('api/sandboxes','POST',{name:n});location.href='sandboxes?id='+r.id}catch(e){flash(e.message,1)}};
 $('b').innerHTML=`<div class="cards"><div class="ccard"><div class="t">Sandboxes</div><div class="v">${sb.length}</div></div><div class="ccard"><div class="t">Snapshots</div><div class="v">${sn.length}</div></div><div class="ccard"><div class="t">Storage used</div><div class="v">${kb(sb.reduce((a,s)=>a+(s.bytes||0),0))}</div></div><div class="ccard"><div class="t">Services running</div><div class="v">${rt.services_running??0} / ${rt.max_services??3}</div></div></div>
 <div class="card" style="padding:0"><table><thead><tr><th>Name</th><th>ID</th><th>Owner</th><th>Storage</th><th>TTL</th><th>Created</th></tr></thead><tbody>${sb.map(s=>`<tr class="r" onclick="location.href='sandboxes?id=${s.id}'"><td><b>${esc(s.name||s.id)}</b></td><td class="mono">${esc(s.id)}</td><td>${esc(s.owner||'')}</td><td>${kb(s.bytes)}</td><td>${s.ttl_hours}h</td><td>${dt(s.created)}</td></tr>`).join('')||`<tr><td colspan="6">${emptyState('terminal','No sandboxes','Run agent code in an isolated container.')}</td></tr>`}</tbody></table></div>
 <div class="card" style="padding:0" id="vcomputers"><div class="h4" style="padding:12px 14px 0">Virtual computers</div><table><thead><tr><th>Name</th><th>Kind</th><th>Status</th><th>Core</th><th>Size</th><th>Internet</th></tr></thead><tbody>${vc.map(v=>`<tr><td><b>${esc(v.name||v.id)}</b></td><td>${esc(v.kind||'computer')}</td><td><span class="chip ${v.status==='running'?'ok':v.status==='failed'?'er':''}">${esc(v.status)}</span></td><td>${esc(v.core||'')}</td><td>${esc(v.size||'')}</td><td>${esc(v.internet||'off')}</td></tr>`).join('')||`<tr><td colspan="6" class="muted">No virtual computers yet.</td></tr>`}</tbody></table></div>
 <div class="card"><div class="h4" style="margin-bottom:6px">Limits &amp; security</div><div class="muted" style="font-size:13px;line-height:1.7">• Isolation: <b>${esc(rt.runtime||'runc')}</b> · no network for code runs · read-only root filesystem · runs as user nobody<br>• 256 MB RAM, 0.5 CPU, 64 processes per container; 50 MB of files per sandbox<br>• Files persist per sandbox until its TTL expires; snapshots can be restored or cloned; volumes can be mounted into several sandboxes<br>• Services are reachable only through the signed-in, HTTPS-only proxy; they have no internet access and stop automatically after their TTL<br>• CLI / SDK: <span class="mono">python -m agentos_sandbox --help</span></div></div>`}
async function one(id){const sb=(await api('api/sandboxes')).find(x=>x.id===id);if(!sb){flash('Sandbox not found',1);return list()}let TAB=QS.get('tab')||'files';
 $('h').innerHTML=`<div class="muted" style="font-size:12px;margin-bottom:6px"><a href="sandboxes">Sandboxes</a> / ${esc(sb.name||id)}</div>`+hdr('terminal',esc(sb.name||id),`<span class="chip mono">${esc(id)}</span><span class="chip">TTL ${sb.ttl_hours}h</span>`,`<button class="r" id="sdel">${ICN('trash')}Delete</button>`)+tabsHtml([['files','Files'],['run','Run'],['snapshots','Snapshots'],['services','Services']],TAB);
 $('sdel').onclick=async()=>{if(!confirm('Delete this sandbox and all its files?'))return;await api('api/sandboxes/'+id,'DELETE');location.href='sandboxes'};
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{TAB=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('on',x===b));draw()});
 const draw=async()=>{const b=$('b');
  if(TAB==='files'){const F=await api('api/sandboxes/'+id+'/files');b.innerHTML=`<div class="toolbar"><input type="file" id="fu"><button id="fup">${ICN('upload')}Upload</button><span class="sp"></span><span class="muted">${kb(F.reduce((a,f)=>a+f.bytes,0))} of 50 MB</span></div><div class="card" style="padding:0"><table><thead><tr><th>Path</th><th>Size</th><th>Modified</th><th></th></tr></thead><tbody>${F.map(f=>`<tr><td class="mono" translate="no">${esc(f.path)}</td><td>${kb(f.bytes)}</td><td>${dt(new Date(f.mtime*1000).toISOString())}</td><td style="text-align:right"><a class="btn gh" href="api/sandboxes/${id}/files/${encodeURIComponent(f.path)}">${ICN('download')}</a><button class="gh" data-rm="${esc(f.path)}">${ICN('trash')}</button></td></tr>`).join('')||`<tr><td colspan="4" class="muted">No files yet. Upload one, or write files from code in the Run tab.</td></tr>`}</tbody></table></div>`;
   $('fup').onclick=async()=>{const f=$('fu').files[0];if(!f)return;const fd=new FormData();fd.append('file',f);fd.append('path',f.name);try{await api('api/sandboxes/'+id+'/files','POST',fd);flash('Uploaded');draw()}catch(e){flash(e.message,1)}};
   b.querySelectorAll('[data-rm]').forEach(x=>x.onclick=async()=>{if(confirm('Delete '+x.dataset.rm+'?')){await api('api/sandboxes/'+id+'/files/'+encodeURIComponent(x.dataset.rm),'DELETE');draw()}})}
  else if(TAB==='run'){const V=await api('api/sandbox_volumes').catch(()=>[]);b.innerHTML=`<div class="grid2" style="align-items:start"><div class="card"><div class="h4">Python code</div><textarea id="rc" rows="14" class="mono" style="width:100%">import os\nprint(os.listdir('.'))\nopen('hello.txt','w').write('hi')</textarea><label>Mount volumes</label>${V.map(v=>`<label style="display:flex;gap:6px;font-weight:400"><input type="checkbox" class="rv" value="${esc(v.name)}">/mnt/${esc(v.name)} <select class="rvm" data-v="${esc(v.name)}"><option value="rw">read-write</option><option value="ro">read-only</option></select></label>`).join('')||'<div class="muted">No volumes.</div>'}<div class="row" style="margin-top:10px"><label>Timeout (s)</label><input id="rt" type="number" value="30" min="1" max="120" style="width:80px"><span class="sp"></span><button id="rgo">${ICN('play')}Run</button></div></div><div class="card"><div class="h4">Output</div><pre id="ro" style="min-height:240px;white-space:pre-wrap">–</pre></div></div>`;
   $('rgo').onclick=async()=>{$('ro').textContent='Running…';const m=[...b.querySelectorAll('.rv:checked')].map(x=>({volume:x.value,readonly:b.querySelector(`.rvm[data-v="${x.value}"]`).value==='ro'}));try{const r=await api('api/sandboxes/'+id+(m.length?'/exec_mounted':'/exec'),'POST',{code:$('rc').value,timeout:+$('rt').value,mounts:m});$('ro').textContent=`exit ${r.exit} · ${r.ms} ms\n\n${r.stdout||''}${r.stderr?'\n[stderr]\n'+r.stderr:''}`}catch(e){$('ro').textContent=e.message}}}
  else if(TAB==='snapshots'){const S=(await api('api/sandbox_snapshots')).filter(x=>x.sandbox_id===id);b.innerHTML=`<div class="toolbar"><button id="snn">${ICN('camera')}Take snapshot</button></div><div class="card" style="padding:0"><table><thead><tr><th>Name</th><th>ID</th><th>Size</th><th>Created</th><th></th></tr></thead><tbody>${S.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td class="mono">${esc(x.id)}</td><td>${kb(x.bytes)}</td><td>${dt(x.created)}</td><td style="text-align:right"><button class="g sm" data-rs="${x.id}">Restore</button> <button class="g sm" data-cl="${x.id}">Clone</button> <button class="gh" data-sd="${x.id}">${ICN('trash')}</button></td></tr>`).join('')||`<tr><td colspan="5" class="muted">No snapshots of this sandbox yet.</td></tr>`}</tbody></table></div>`;
   $('snn').onclick=async()=>{const n=prompt('Snapshot name','snapshot');if(!n)return;await api('api/sandboxes/'+id+'/snapshots','POST',{name:n});flash('Snapshot taken');draw()};
   b.querySelectorAll('[data-rs]').forEach(x=>x.onclick=async()=>{if(!confirm('Replace all files in this sandbox with the snapshot?'))return;const r=await api('api/sandbox_snapshots/'+x.dataset.rs+'/restore/'+id,'POST');flash('Restored');draw()});
   b.querySelectorAll('[data-cl]').forEach(x=>x.onclick=async()=>{const n=prompt('New sandbox name','clone');if(!n)return;const r=await api('api/sandbox_snapshots/'+x.dataset.cl+'/clone','POST',{name:n});location.href='sandboxes?id='+r.id});
   b.querySelectorAll('[data-sd]').forEach(x=>x.onclick=async()=>{if(confirm('Delete snapshot?')){await api('api/sandbox_snapshots/'+x.dataset.sd,'DELETE');draw()}})}
  else{const L=await api('api/sandboxes/'+id+'/services');b.innerHTML=`<div class="card"><div class="h4">Start a service</div><div class="muted" style="font-size:12.5px">Runs a long-lived process from this sandbox's files. It is reachable only through the signed-in HTTPS proxy below and has no internet access.</div><div class="row" style="margin-top:8px"><div style="flex:3"><label>Command</label><input id="vc" class="mono" value="python -m http.server 8000" style="width:100%"></div><div><label>Port</label><input id="vp" type="number" value="8000" style="width:90px"></div><div><label>Stop after (min)</label><input id="vt" type="number" value="60" min="5" max="480" style="width:90px"></div><div style="align-self:end"><button id="vgo">${ICN('play')}Start</button></div></div></div>
   <div class="card" style="padding:0"><table><thead><tr><th>Name</th><th>Command</th><th>Status</th><th>Runtime</th><th>Expires</th><th></th></tr></thead><tbody>${L.map(v=>`<tr><td><b>${esc(v.name)}</b> <span class="mono muted">${esc(v.id)}</span></td><td class="mono" style="font-size:12px" translate="no">${esc((v.command||[]).join(' '))} :${v.port}</td><td>${v.status==='running'?'<span class="chip ok">Running</span>':`<span class="chip">${esc(v.status)}</span>`}</td><td>${esc(v.runtime||'')}</td><td>${['running','starting'].includes(v.status)?`in ${Math.max(0,Math.round((new Date(v.expires)-Date.now())/60000))} min`:'–'}</td><td style="text-align:right">${['running','starting'].includes(v.status)?`<a class="btn g sm" target="_blank" rel="noopener" href="api/sandboxes/${id}/svc/${v.id}/">${ICN('external-link')}Open</a> <button class="g sm" data-lg="${v.id}">Logs</button> <button class="g sm" data-sl="${v.id}">${ICN('share-2')}Share link</button> <button class="gh" data-st="${v.id}">${ICN('square')}Stop</button>`:''}</td></tr>`).join('')||`<tr><td colspan="6" class="muted">No services yet.</td></tr>`}</tbody></table></div>`;
   $('vgo').onclick=async()=>{const bt=$('vgo');bt.disabled=true;try{const r=await api('api/sandboxes/'+id+'/services','POST',{command:$('vc').value,port:+$('vp').value,ttl_minutes:+$('vt').value});flash(r.status==='running'?'Service running':'Service starting');draw()}catch(e){flash(e.message,1);bt.disabled=false}};
   b.querySelectorAll('[data-st]').forEach(x=>x.onclick=async()=>{await api('api/sandboxes/'+id+'/services/'+x.dataset.st,'DELETE');flash('Stopped');draw()});
   b.querySelectorAll('[data-sl]').forEach(x=>x.onclick=()=>pane('Share a service link',`<div class="muted" style="font-size:13px;margin-bottom:8px">Anyone with the link can open this one service for a limited time, without an account. The link is revoked when it expires, when you revoke it, or when the service stops.</div><label>Valid for</label><select id="slt"><option value="600">10 minutes</option><option value="3600" selected>1 hour</option><option value="86400">24 hours</option></select><div class="row" style="margin-top:10px"><button id="slgo">Create link</button><button class="g" id="slrv">Revoke all links</button></div><div id="slout"></div>`,p=>{p.querySelector('#slgo').onclick=async()=>{try{const r=await api('api/sandboxes/'+id+'/service-url','POST',{service:x.dataset.sl,expires_in_seconds:+p.querySelector('#slt').value});p.querySelector('#slout').innerHTML=`<div class="card" style="margin-top:12px"><b>Browser link</b> <small class="muted">expires ${esc(dt(r.expires_at))}</small><pre style="user-select:all;white-space:pre-wrap;word-break:break-all">${esc(r.browser_url)}</pre><b>For programs</b><pre style="user-select:all;white-space:pre-wrap;word-break:break-all">curl -H "${esc(r.header)}: ${esc(r.token)}" ${esc(r.service_url)}</pre></div>`}catch(e){flash(e.message,1)}};p.querySelector('#slrv').onclick=async()=>{if(!confirm('Revoke every link of this service?'))return;await api('api/sandboxes/'+id+'/services/'+x.dataset.sl+'/revoke-links','POST');flash('Links revoked')}}));
   b.querySelectorAll('[data-lg]').forEach(x=>x.onclick=async()=>{const r=await api('api/sandboxes/'+id+'/services/'+x.dataset.lg+'/logs');pane('Service logs',`<pre style="max-height:70vh;white-space:pre-wrap">${esc(r.logs||'(empty)')}</pre>`)})}};
 draw()}
(QS.get('id')?one(QS.get('id')):list()).catch(e=>flash(e.message,1));
""")

PAGES = {"/builder": BUILD, "/evaluators": EVALS, "/annotation": AQ, "/context": CONTEXT, "/dashboards": DASH, "/apps": APPS, "/gateway": GATEWAY, "/sandboxes": SANDBOX}
